$svc = Get-Service W32Time -ErrorAction SilentlyContinue
if ($svc.Status -eq 'Running' -and $svc.StartType -eq 'Automatic') {
    Write-Output 'W32Time healthy'; exit 0
} else {
    Write-Output 'W32Time not running/automatic'; exit 1
}

try {
    Set-Service W32Time -StartupType Automatic -ErrorAction Stop
    Start-Service W32Time -ErrorAction Stop
    Write-Output 'W32Time fixed'; exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"; exit 1
}
